package com.gwsheridan.worldsunwritten.testkit;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

/** Java-only launcher for exported projects and a user-selected installed NeoForge runtime. */
public final class PackTestKit {
    private static final String NEO="26.3.0.103";
    public static void main(String[] args)throws Exception{
        if(args.length==0||Arrays.asList(args).contains("--help")){System.out.println("Worlds Unwritten pack test kit (Java 25)\njava -jar Worlds-Unwritten-test-kit.jar --server INSTALLED_NEOFORGE_SERVER --export EXPORTED_PROJECT --providers PROVIDER_JAR_FOLDER --output NEW_FOLDER --eula true\nUses only a new disposable world. Supply legally installed Minecraft/NeoForge and required provider mods. No Gradle, source checkout or Node is required.");return;}
        var options=new HashMap<String,String>();if(args.length%2!=0)throw new IllegalArgumentException("Use option/value pairs; see --help");for(int i=0;i<args.length;i+=2)if(!Set.of("--server","--export","--providers","--output","--eula").contains(args[i])||options.put(args[i],args[i+1])!=null)throw new IllegalArgumentException("Unknown or repeated option "+args[i]);for(String key:List.of("--server","--export","--providers","--output","--eula"))if(!options.containsKey(key))throw new IllegalArgumentException("Missing "+key);
        if(!options.get("--eula").equals("true"))throw new IllegalArgumentException("Read the Minecraft EULA and supply --eula true to accept it for this disposable test server.");
        Path runtime=Path.of(options.get("--server")).toRealPath(),project=Path.of(options.get("--export")).toRealPath(),providers=Path.of(options.get("--providers")).toRealPath(),output=Path.of(options.get("--output")).toAbsolutePath().normalize();
        if(Files.exists(output)||output.startsWith(runtime)||output.startsWith(project)||output.startsWith(providers))throw new IOException("Choose a new output folder outside the runtime, project and provider folders.");
        var properties=new Properties();try(var in=Files.newInputStream(project.resolve("testkit.properties"))){properties.load(in);}if(!properties.getProperty("format","").equals("2")||!properties.getProperty("worldsunwritten","").equals("2.0.0")||!properties.getProperty("neoforge","").equals(NEO))throw new IOException("This test kit requires a matching 2.0.0 project and NeoForge "+NEO);
        var bundle=project.resolve(properties.getProperty("bundle","")).normalize();if(!bundle.startsWith(project)||!Files.isRegularFile(bundle,LinkOption.NOFOLLOW_LINKS)||!sha(bundle).equals(properties.getProperty("sha256","")))throw new IOException("Exported preset checksum is invalid");
        String platform=System.getProperty("os.name").toLowerCase(Locale.ROOT).contains("win")?"win_args.txt":"unix_args.txt";Path relativeArgs=Path.of("libraries/net/neoforged/neoforge/"+NEO+"/"+platform);if(!Files.isRegularFile(runtime.resolve(relativeArgs)))throw new IOException("Select an installed NeoForge "+NEO+" server containing "+relativeArgs);
        var home=Path.of(PackTestKit.class.getProtectionDomain().getCodeSource().getLocation().toURI()).getParent();for(String file:List.of("Worlds-Unwritten.jar","Worlds-Unwritten-pack-test.jar"))if(!Files.isRegularFile(home.resolve("lib").resolve(file)))throw new IOException("Keep the complete test-kit ZIP together; missing lib/"+file);
        Files.createDirectory(output);var server=output.resolve("server");Files.createDirectory(server);copyTree(runtime.resolve("libraries"),server.resolve("libraries"));Files.createDirectory(server.resolve("mods"));var inventory=new TreeMap<String,String>();
        for(String file:List.of("Worlds-Unwritten.jar","Worlds-Unwritten-pack-test.jar")){var source=home.resolve("lib").resolve(file);Files.copy(source,server.resolve("mods").resolve(file));inventory.put(file,sha(source));}
        try(var files=Files.list(providers)){for(var source:files.sorted().toList())if(source.getFileName().toString().endsWith(".jar")){if(!Files.isRegularFile(source,LinkOption.NOFOLLOW_LINKS))throw new IOException("Provider must be a regular JAR: "+source);Files.copy(source,server.resolve("mods").resolve(source.getFileName()));inventory.put(source.getFileName().toString(),sha(source));}}
        var config=server.resolve("config/worldsunwritten");Files.createDirectories(config.resolve("bundles"));Files.copy(bundle,config.resolve("bundles/preset.zip"));Files.writeString(config.resolve("developer.json"),"{\"format\":1,\"bundle\":\"preset.zip\",\"developer_mode\":false}\n");Files.writeString(server.resolve("eula.txt"),"eula=true\n");
        // A fresh loopback-only, empty-whitelist server cannot accept a remote player.
        int port;try(var socket=new java.net.ServerSocket(0,0,java.net.InetAddress.getLoopbackAddress())){port=socket.getLocalPort();}Files.writeString(server.resolve("server.properties"),"server-ip=127.0.0.1\nserver-port="+port+"\nonline-mode=false\nwhite-list=true\nenforce-whitelist=true\nmax-players=1\nview-distance=2\nsimulation-distance=2\nmanagement-server-enabled=false\nenable-rcon=false\nlog-ips=false\n");Files.writeString(server.resolve("whitelist.json"),"[]\n");
        Instant start=Instant.now();String status="failed",problem="";try{for(int stage=1;stage<=2;stage++)run(server,relativeArgs,output.resolve("stage-"+stage+".log"),stage);status="passed";}catch(Exception error){problem=Objects.toString(error.getMessage(),error.getClass().getSimpleName());}finally{var report=new StringBuilder("{\"format\":1,\"status\":").append(json(status)).append(",\"elapsed_seconds\":").append(Duration.between(start,Instant.now()).toSeconds()).append(",\"bundle_sha256\":").append(json(sha(bundle))).append(",\"error\":").append(json(problem)).append(",\"mods\":{");boolean first=true;for(var e:inventory.entrySet()){if(!first)report.append(',');first=false;report.append(json(e.getKey())).append(':').append(json(e.getValue()));}report.append("}}\n");Files.writeString(output.resolve("results.json"),report);}
        System.out.println("Pack validation "+status+": "+output.resolve("results.json"));if(!status.equals("passed"))throw new IllegalStateException(problem);
    }
    private static void run(Path server,Path args,Path log,int stage)throws Exception{
        String java=ProcessHandle.current().info().command().orElseThrow();var process=new ProcessBuilder(java,"-Xmx1600m","-XX:ActiveProcessorCount=4","@"+args.toString(),"--nogui").directory(server.toFile()).redirectErrorStream(true).start();var text=new StringBuilder();var failure=new AtomicReference<Throwable>();
        Thread reader=Thread.ofPlatform().daemon().start(()->{try(var in=process.inputReader(StandardCharsets.UTF_8);var out=Files.newBufferedWriter(log)){String line;while((line=in.readLine())!=null){out.write(line);out.newLine();out.flush();synchronized(text){text.append(line).append('\n');if(text.length()>4_000_000)text.delete(0,text.length()-4_000_000);}}}catch(Throwable error){failure.set(error);}});
        try(var input=process.outputWriter(StandardCharsets.UTF_8)){await(process,text,"Done (",180,failure);input.write("wa_pack_test "+stage+"\n");input.flush();await(process,text,"WA_PACK_TEST_PASS stage="+stage,180,failure);input.write("save-all flush\n");input.flush();await(process,text,"Saved the game",120,failure);input.write("stop\n");input.flush();if(!process.waitFor(60,TimeUnit.SECONDS)||process.exitValue()!=0)throw new IOException("Server shutdown failed; inspect "+log);}finally{if(process.isAlive()){process.destroy();if(!process.waitFor(10,TimeUnit.SECONDS))process.destroyForcibly();}reader.join(5000);}
    }
    private static void await(Process process,StringBuilder text,String marker,int seconds,AtomicReference<Throwable> failure)throws Exception{long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(seconds);while(System.nanoTime()<deadline){synchronized(text){if(text.indexOf("WA_PACK_TEST_FAILED")>=0)throw new IOException("Pack fixture failed; inspect stage logs");if(text.indexOf(marker)>=0)return;}if(failure.get()!=null)throw new IOException("Cannot read server output",failure.get());if(!process.isAlive())throw new IOException("Server exited before "+marker);Thread.sleep(100);}throw new IOException("Timed out waiting for "+marker);}
    private static void copyTree(Path source,Path target)throws IOException{Files.walkFileTree(source,new SimpleFileVisitor<>(){@Override public FileVisitResult preVisitDirectory(Path directory,java.nio.file.attribute.BasicFileAttributes attributes)throws IOException{if(Files.isSymbolicLink(directory))throw new IOException("Runtime symlink is unsupported");Files.createDirectories(target.resolve(source.relativize(directory)));return FileVisitResult.CONTINUE;}@Override public FileVisitResult visitFile(Path file,java.nio.file.attribute.BasicFileAttributes attributes)throws IOException{if(!attributes.isRegularFile()||Files.isSymbolicLink(file))throw new IOException("Runtime contains an unsupported file");Files.copy(file,target.resolve(source.relativize(file)));return FileVisitResult.CONTINUE;}});}
    private static String sha(Path file)throws Exception{var digest=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(file)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);}return HexFormat.of().formatHex(digest.digest());}
    private static String json(String value){var out=new StringBuilder("\"");for(char c:value.toCharArray())switch(c){case '"'->out.append("\\\"");case '\\'->out.append("\\\\");case '\n'->out.append("\\n");case '\r'->out.append("\\r");case '\t'->out.append("\\t");default->{if(c<32)out.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else out.append(c);}}return out.append('"').toString();}
}
